import type { NistCatalogFamily } from "../types.js";

// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_IA: NistCatalogFamily = {"code":"IA","name":"Identification and Authentication","controls":[{"id":"IA-1","oscal_id":"ia-1","family":"IA","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> identification and authentication policy that:\n    <organization-defined parameter> identification and authentication policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the identification and authentication policy and the associated identification and authentication controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the identification and authentication policy and procedures; and\nc. Review and update the current identification and authentication:\n  Review and update the current identification and authentication:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Identification and authentication policy and procedures address the controls in the IA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of identification and authentication policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to identification and authentication policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"ia-1_prm_1","label":"organization-defined personnel or roles"},{"id":"ia-01_odp.01","label":"personnel or roles"},{"id":"ia-01_odp.02","label":"personnel or roles"},{"id":"ia-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"ia-01_odp.04","label":"official"},{"id":"ia-01_odp.05","label":"frequency"},{"id":"ia-01_odp.06","label":"events"},{"id":"ia-01_odp.07","label":"frequency"},{"id":"ia-01_odp.08","label":"events"}],"objectives":[{"id":"ia-1_obj.a-1","label":"IA-01a.[01]","text":"an identification and authentication policy is developed and documented;"},{"id":"ia-1_obj.a-2","label":"IA-01a.[02]","text":"the identification and authentication policy is disseminated to {{ insert: param, ia-01_odp.01 }};"},{"id":"ia-1_obj.a-3","label":"IA-01a.[03]","text":"identification and authentication procedures to facilitate the implementation of the identification and authentication policy and associated identification and authentication controls are developed and documented;"},{"id":"ia-1_obj.a-4","label":"IA-01a.[04]","text":"the identification and authentication procedures are disseminated to {{ insert: param, ia-01_odp.02 }};"},{"id":"ia-1_obj.a.1.a-1","label":"IA-01a.01(a)[01]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses purpose;"},{"id":"ia-1_obj.a.1.a-2","label":"IA-01a.01(a)[02]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses scope;"},{"id":"ia-1_obj.a.1.a-3","label":"IA-01a.01(a)[03]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses roles;"},{"id":"ia-1_obj.a.1.a-4","label":"IA-01a.01(a)[04]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses responsibilities;"},{"id":"ia-1_obj.a.1.a-5","label":"IA-01a.01(a)[05]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses management commitment;"},{"id":"ia-1_obj.a.1.a-6","label":"IA-01a.01(a)[06]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses coordination among organizational entities;"},{"id":"ia-1_obj.a.1.a-7","label":"IA-01a.01(a)[07]","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy addresses compliance;"},{"id":"ia-1_obj.a.1.b","label":"IA-01a.01(b)","text":"the {{ insert: param, ia-01_odp.03 }} identification and authentication policy is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines;"},{"id":"ia-1_obj.b","label":"IA-01b.","text":"the {{ insert: param, ia-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the identification and authentication policy and procedures;"},{"id":"ia-1_obj.c.1-1","label":"IA-01c.01[01]","text":"the current identification and authentication policy is reviewed and updated {{ insert: param, ia-01_odp.05 }};"},{"id":"ia-1_obj.c.1-2","label":"IA-01c.01[02]","text":"the current identification and authentication policy is reviewed and updated following {{ insert: param, ia-01_odp.06 }};"},{"id":"ia-1_obj.c.2-1","label":"IA-01c.02[01]","text":"the current identification and authentication procedures are reviewed and updated {{ insert: param, ia-01_odp.07 }};"},{"id":"ia-1_obj.c.2-2","label":"IA-01c.02[02]","text":"the current identification and authentication procedures are reviewed and updated following {{ insert: param, ia-01_odp.08 }}."}],"methods":[{"method":"examine","label":"IA-01-Examine"},{"method":"interview","label":"IA-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"FIPS 201-2"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-63-3"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"},{"title":"SP 800-100"},{"title":"IR 7874"}],"related_controls":["AC-1","PM-9","PS-8","SI-12"]},{"id":"IA-2","oscal_id":"ia-2","family":"IA","title":"Identification and Authentication (Organizational Users)","statement":"Uniquely identify and authenticate organizational users and associate that unique identification with processes acting on behalf of those users.","supplemental_guidance":"Organizations can satisfy the identification and authentication requirements by complying with the requirements in [HSPD 12](#f16e438e-7114-4144-bfe2-2dfcad8cb2d0) . Organizational users include employees or individuals who organizations consider to have an equivalent status to employees (e.g., contractors and guest researchers). Unique identification and authentication of users applies to all accesses other than those that are explicitly identified in [AC-14](#ac-14) and that occur through the authorized use of group authenticators without individual authentication. Since processes execute on behalf of groups and roles, organizations may require unique identification of individuals in group accounts or for detailed accountability of individual activity.\n\nOrganizations employ passwords, physical authenticators, or biometrics to authenticate user identities or, in the case of multi-factor authentication, some combination thereof. Access to organizational systems is defined as either local access or network access. Local access is any access to organizational systems by users or processes acting on behalf of users, where access is obtained through direct connections without the use of networks. Network access is access to organizational systems by users (or processes acting on behalf of users) where access is obtained through network connections (i.e., nonlocal accesses). Remote access is a type of network access that involves communication through external networks. Internal networks include local area networks and wide area networks.\n\nThe use of encrypted virtual private networks for network connections between organization-controlled endpoints and non-organization-controlled endpoints may be treated as internal networks with respect to protecting the confidentiality and integrity of information traversing the network. Identification and authentication requirements for non-organizational users are described in [IA-8](#ia-8).","implementation_level":"organization","objectives":[{"id":"ia-2_obj-1","label":"IA-02[01]","text":"organizational users are uniquely identified and authenticated;"},{"id":"ia-2_obj-2","label":"IA-02[02]","text":"the unique identification of authenticated organizational users is associated with processes acting on behalf of those users."}],"methods":[{"method":"examine","label":"IA-02-Examine"},{"method":"interview","label":"IA-02-Interview"},{"method":"test","label":"IA-02-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 201-2"},{"title":"FIPS 202"},{"title":"SP 800-63-3"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"},{"title":"SP 800-79-2"},{"title":"SP 800-156"},{"title":"SP 800-166"},{"title":"IR 7539"},{"title":"IR 7676"},{"title":"IR 7817"},{"title":"IR 7849"},{"title":"IR 7870"},{"title":"IR 7874"},{"title":"IR 7966"}],"related_controls":["AC-2","AC-3","AC-4","AC-14","AC-17","AC-18","AU-1","AU-6","IA-4","IA-5","IA-8","IA-13","MA-4","MA-5","PE-2","PL-4","SA-4","SA-8"],"enhancements":[{"id":"IA-2(1)","oscal_id":"ia-2.1","family":"IA","title":"Multi-factor Authentication to Privileged Accounts","statement":"Implement multi-factor authentication for access to privileged accounts.","supplemental_guidance":"Multi-factor authentication requires the use of two or more different factors to achieve authentication. The authentication factors are defined as follows: something you know (e.g., a personal identification number [PIN]), something you have (e.g., a physical authenticator such as a cryptographic private key), or something you are (e.g., a biometric). Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification (PIV) card or the Department of Defense (DoD) Common Access Card (CAC). In addition to authenticating users at the system level (i.e., at logon), organizations may employ authentication mechanisms at the application level, at their discretion, to provide increased security. Regardless of the type of access (i.e., local, network, remote), privileged accounts are authenticated using multi-factor options appropriate for the level of risk. Organizations can add additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access.","implementation_level":"system","methods":[{"method":"examine","label":"IA-02(01)-Examine"},{"method":"interview","label":"IA-02(01)-Interview"},{"method":"test","label":"IA-02(01)-Test"}],"related_controls":["AC-5","AC-6"],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(2)","oscal_id":"ia-2.2","family":"IA","title":"Multi-factor Authentication to Non-privileged Accounts","statement":"Implement multi-factor authentication for access to non-privileged accounts.","supplemental_guidance":"Multi-factor authentication requires the use of two or more different factors to achieve authentication. The authentication factors are defined as follows: something you know (e.g., a personal identification number [PIN]), something you have (e.g., a physical authenticator such as a cryptographic private key), or something you are (e.g., a biometric). Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification card or the DoD Common Access Card. In addition to authenticating users at the system level, organizations may also employ authentication mechanisms at the application level, at their discretion, to provide increased information security. Regardless of the type of access (i.e., local, network, remote), non-privileged accounts are authenticated using multi-factor options appropriate for the level of risk. Organizations can provide additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access.","implementation_level":"system","methods":[{"method":"examine","label":"IA-02(02)-Examine"},{"method":"interview","label":"IA-02(02)-Interview"},{"method":"test","label":"IA-02(02)-Test"}],"related_controls":["AC-5"],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(3)","oscal_id":"ia-2.3","family":"IA","title":"Local Access to Privileged Accounts","statement":"","is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(4)","oscal_id":"ia-2.4","family":"IA","title":"Local Access to Non-privileged Accounts","statement":"","is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(5)","oscal_id":"ia-2.5","family":"IA","title":"Individual Authentication with Group Authentication","statement":"When shared accounts or authenticators are employed, require users to be individually authenticated before granting access to the shared accounts or resources.","supplemental_guidance":"Individual authentication prior to shared group authentication mitigates the risk of using group accounts or authenticators.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-02(05)-Examine"},{"method":"interview","label":"IA-02(05)-Interview"},{"method":"test","label":"IA-02(05)-Test"}],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(6)","oscal_id":"ia-2.6","family":"IA","title":"Access to Accounts —separate Device","statement":"Implement multi-factor authentication for <organization-defined parameter> access to <organization-defined parameter> such that:\n(a) One of the factors is provided by a device separate from the system gaining access; and\n(b) The device meets <strength of mechanism requirements>.","supplemental_guidance":"The purpose of requiring a device that is separate from the system to which the user is attempting to gain access for one of the factors during multi-factor authentication is to reduce the likelihood of compromising authenticators or credentials stored on the system. Adversaries may be able to compromise such authenticators or credentials and subsequently impersonate authorized users. Implementing one of the factors on a separate device (e.g., a hardware token), provides a greater strength of mechanism and an increased level of assurance in the authentication process.","implementation_level":"system","parameters":[{"id":"ia-02.06_odp.01","label":"","choices":["local","network","remote"],"how_many":"one-or-more"},{"id":"ia-02.06_odp.02","label":"","choices":["privileged accounts","non-privileged accounts"],"how_many":"one-or-more"},{"id":"ia-02.06_odp.03","label":"strength of mechanism requirements"}],"objectives":[{"id":"ia-2.6_obj.a","label":"IA-02(06)(a)","text":"multi-factor authentication is implemented for {{ insert: param, ia-02.06_odp.01 }} access to {{ insert: param, ia-02.06_odp.02 }} such that one of the factors is provided by a device separate from the system gaining access;"},{"id":"ia-2.6_obj.b","label":"IA-02(06)(b)","text":"multi-factor authentication is implemented for {{ insert: param, ia-02.06_odp.01 }} access to {{ insert: param, ia-02.06_odp.02 }} such that the device meets {{ insert: param, ia-02.06_odp.03 }}."}],"methods":[{"method":"examine","label":"IA-02(06)-Examine"},{"method":"interview","label":"IA-02(06)-Interview"},{"method":"test","label":"IA-02(06)-Test"}],"related_controls":["AC-6"],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(7)","oscal_id":"ia-2.7","family":"IA","title":"Network Access to Non-privileged Accounts — Separate Device","statement":"","is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(8)","oscal_id":"ia-2.8","family":"IA","title":"Access to Accounts — Replay Resistant","statement":"Implement replay-resistant authentication mechanisms for access to <organization-defined parameter>.","supplemental_guidance":"Authentication processes resist replay attacks if it is impractical to achieve successful authentications by replaying previous authentication messages. Replay-resistant techniques include protocols that use nonces or challenges such as time synchronous or cryptographic authenticators.","implementation_level":"system","parameters":[{"id":"ia-02.08_odp","label":"","choices":["privileged accounts","non-privileged accounts"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"IA-02(08)-Examine"},{"method":"interview","label":"IA-02(08)-Interview"},{"method":"test","label":"IA-02(08)-Test"}],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(9)","oscal_id":"ia-2.9","family":"IA","title":"Network Access to Non-privileged Accounts — Replay Resistant","statement":"","is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(10)","oscal_id":"ia-2.10","family":"IA","title":"Single Sign-on","statement":"Provide a single sign-on capability for <system accounts and services>.","supplemental_guidance":"Single sign-on enables users to log in once and gain access to multiple system resources. Organizations consider the operational efficiencies provided by single sign-on capabilities with the risk introduced by allowing access to multiple systems via a single authentication event. Single sign-on can present opportunities to improve system security, for example by providing the ability to add multi-factor authentication for applications and systems (existing and new) that may not be able to natively support multi-factor authentication.","implementation_level":"system","parameters":[{"id":"ia-02.10_odp","label":"system accounts and services"}],"methods":[{"method":"examine","label":"IA-02(10)-Examine"},{"method":"interview","label":"IA-02(10)-Interview"},{"method":"test","label":"IA-02(10)-Test"}],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(11)","oscal_id":"ia-2.11","family":"IA","title":"Remote Access — Separate Device","statement":"","is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(12)","oscal_id":"ia-2.12","family":"IA","title":"Acceptance of PIV Credentials","statement":"Accept and electronically verify Personal Identity Verification-compliant credentials.","supplemental_guidance":"Acceptance of Personal Identity Verification (PIV)-compliant credentials applies to organizations implementing logical access control and physical access control systems. PIV-compliant credentials are those credentials issued by federal agencies that conform to FIPS Publication 201 and supporting guidance documents. The adequacy and reliability of PIV card issuers are authorized using [SP 800-79-2](#10963761-58fc-4b20-b3d6-b44a54daba03) . Acceptance of PIV-compliant credentials includes derived PIV credentials, the use of which is addressed in [SP 800-166](#e8552d48-cf41-40aa-8b06-f45f7fb4706c) . The DOD Common Access Card (CAC) is an example of a PIV credential.","implementation_level":"system","methods":[{"method":"examine","label":"IA-02(12)-Examine"},{"method":"interview","label":"IA-02(12)-Interview"},{"method":"test","label":"IA-02(12)-Test"}],"is_enhancement":true,"parent_id":"IA-2"},{"id":"IA-2(13)","oscal_id":"ia-2.13","family":"IA","title":"Out-of-band Authentication","statement":"Implement the following out-of-band authentication mechanisms under <conditions>: <out-of-band authentication>.","supplemental_guidance":"Out-of-band authentication refers to the use of two separate communication paths to identify and authenticate users or devices to an information system. The first path (i.e., the in-band path) is used to identify and authenticate users or devices and is generally the path through which information flows. The second path (i.e., the out-of-band path) is used to independently verify the authentication and/or requested action. For example, a user authenticates via a notebook computer to a remote server to which the user desires access and requests some action of the server via that communication path. Subsequently, the server contacts the user via the user’s cell phone to verify that the requested action originated from the user. The user may confirm the intended action to an individual on the telephone or provide an authentication code via the telephone. Out-of-band authentication can be used to mitigate actual or suspected \"man-in the-middle\" attacks. The conditions or criteria for activation include suspicious activities, new threat indicators, elevated threat levels, or the impact or classification level of information in requested transactions.","implementation_level":"system","parameters":[{"id":"ia-02.13_odp.01","label":"out-of-band authentication"},{"id":"ia-02.13_odp.02","label":"conditions"}],"methods":[{"method":"examine","label":"IA-02(13)-Examine"},{"method":"interview","label":"IA-02(13)-Interview"},{"method":"test","label":"IA-02(13)-Test"}],"related_controls":["IA-10","IA-11","SC-37"],"is_enhancement":true,"parent_id":"IA-2"}]},{"id":"IA-3","oscal_id":"ia-3","family":"IA","title":"Device Identification and Authentication","statement":"Uniquely identify and authenticate <devices and/or types of devices> before establishing a <organization-defined parameter> connection.","supplemental_guidance":"Devices that require unique device-to-device identification and authentication are defined by type, device, or a combination of type and device. Organization-defined device types include devices that are not owned by the organization. Systems use shared known information (e.g., Media Access Control [MAC], Transmission Control Protocol/Internet Protocol [TCP/IP] addresses) for device identification or organizational authentication solutions (e.g., Institute of Electrical and Electronics Engineers (IEEE) 802.1x and Extensible Authentication Protocol [EAP], RADIUS server with EAP-Transport Layer Security [TLS] authentication, Kerberos) to identify and authenticate devices on local and wide area networks. Organizations determine the required strength of authentication mechanisms based on the security categories of systems and mission or business requirements. Because of the challenges of implementing device authentication on a large scale, organizations can restrict the application of the control to a limited number/type of devices based on mission or business needs.","implementation_level":"system","parameters":[{"id":"ia-03_odp.01","label":"devices and/or types of devices"},{"id":"ia-03_odp.02","label":"","choices":["local","remote","network"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"IA-03-Examine"},{"method":"interview","label":"IA-03-Interview"},{"method":"test","label":"IA-03-Test"}],"related_controls":["AC-17","AC-18","AC-19","AU-6","CA-3","CA-9","IA-4","IA-5","IA-9","IA-11","IA-13","SI-4"],"enhancements":[{"id":"IA-3(1)","oscal_id":"ia-3.1","family":"IA","title":"Cryptographic Bidirectional Authentication","statement":"Authenticate <devices and/or types of devices> before establishing <organization-defined parameter> connection using bidirectional authentication that is cryptographically based.","supplemental_guidance":"A local connection is a connection with a device that communicates without the use of a network. A network connection is a connection with a device that communicates through a network. A remote connection is a connection with a device that communicates through an external network. Bidirectional authentication provides stronger protection to validate the identity of other devices for connections that are of greater risk.","implementation_level":"system","parameters":[{"id":"ia-03.01_odp.01","label":"devices and/or types of devices"},{"id":"ia-03.01_odp.02","label":"","choices":["local","remote","network"],"how_many":"one-or-more"}],"methods":[{"method":"examine","label":"IA-03(01)-Examine"},{"method":"interview","label":"IA-03(01)-Interview"},{"method":"test","label":"IA-03(01)-Test"}],"related_controls":["SC-8","SC-12","SC-13"],"is_enhancement":true,"parent_id":"IA-3"},{"id":"IA-3(2)","oscal_id":"ia-3.2","family":"IA","title":"Cryptographic Bidirectional Network Authentication","statement":"","is_enhancement":true,"parent_id":"IA-3"},{"id":"IA-3(3)","oscal_id":"ia-3.3","family":"IA","title":"Dynamic Address Allocation","statement":"(a) Where addresses are allocated dynamically, standardize dynamic address allocation lease information and the lease duration assigned to devices in accordance with <organization-defined lease information and lease duration> ; and\n(b) Audit lease information when assigned to a device.","supplemental_guidance":"The Dynamic Host Configuration Protocol (DHCP) is an example of a means by which clients can dynamically receive network address assignments.","implementation_level":"organization","parameters":[{"id":"ia-3.3_prm_1","label":"organization-defined lease information and lease duration"},{"id":"ia-03.03_odp.01","label":"lease information"},{"id":"ia-03.03_odp.02","label":"lease duration"}],"objectives":[{"id":"ia-3.3_obj.a-1","label":"IA-03(03)(a)[01]","text":"dynamic address allocation lease information assigned to devices where addresses are allocated dynamically are standardized in accordance with {{ insert: param, ia-03.03_odp.01 }};"},{"id":"ia-3.3_obj.a-2","label":"IA-03(03)(a)[02]","text":"dynamic address allocation lease duration assigned to devices where addresses are allocated dynamically are standardized in accordance with {{ insert: param, ia-03.03_odp.02 }};"},{"id":"ia-3.3_obj.b","label":"IA-03(03)(b)","text":"lease information is audited when assigned to a device."}],"methods":[{"method":"examine","label":"IA-03(03)-Examine"},{"method":"interview","label":"IA-03(03)-Interview"},{"method":"test","label":"IA-03(03)-Test"}],"related_controls":["AU-2"],"is_enhancement":true,"parent_id":"IA-3"},{"id":"IA-3(4)","oscal_id":"ia-3.4","family":"IA","title":"Device Attestation","statement":"Handle device identification and authentication based on attestation by <configuration management process>.","supplemental_guidance":"Device attestation refers to the identification and authentication of a device based on its configuration and known operating state. Device attestation can be determined via a cryptographic hash of the device. If device attestation is the means of identification and authentication, then it is important that patches and updates to the device are handled via a configuration management process such that the patches and updates are done securely and do not disrupt identification and authentication to other devices.","implementation_level":"organization","parameters":[{"id":"ia-03.04_odp","label":"configuration management process"}],"methods":[{"method":"examine","label":"IA-03(04)-Examine"},{"method":"interview","label":"IA-03(04)-Interview"},{"method":"test","label":"IA-03(04)-Test"}],"related_controls":["CM-2","CM-3","CM-6"],"is_enhancement":true,"parent_id":"IA-3"}]},{"id":"IA-4","oscal_id":"ia-4","family":"IA","title":"Identifier Management","statement":"Manage system identifiers by:\na. Receiving authorization from <personnel or roles> to assign an individual, group, role, service, or device identifier;\nb. Selecting an identifier that identifies an individual, group, role, service, or device;\nc. Assigning the identifier to the intended individual, group, role, service, or device; and\nd. Preventing reuse of identifiers for <time period>.","supplemental_guidance":"Common device identifiers include Media Access Control (MAC) addresses, Internet Protocol (IP) addresses, or device-unique token identifiers. The management of individual identifiers is not applicable to shared system accounts. Typically, individual identifiers are the usernames of the system accounts assigned to those individuals. In such instances, the account management activities of [AC-2](#ac-2) use account names provided by [IA-4](#ia-4) . Identifier management also addresses individual identifiers not necessarily associated with system accounts. Preventing the reuse of identifiers implies preventing the assignment of previously used individual, group, role, service, or device identifiers to different individuals, groups, roles, services, or devices.","implementation_level":"organization","parameters":[{"id":"ia-04_odp.01","label":"personnel or roles"},{"id":"ia-04_odp.02","label":"time period"}],"objectives":[{"id":"ia-4_obj.a","label":"IA-04a.","text":"system identifiers are managed by receiving authorization from {{ insert: param, ia-04_odp.01 }} to assign to an individual, group, role, or device identifier;"},{"id":"ia-4_obj.b","label":"IA-04b.","text":"system identifiers are managed by selecting an identifier that identifies an individual, group, role, service, or device;"},{"id":"ia-4_obj.c","label":"IA-04c.","text":"system identifiers are managed by assigning the identifier to the intended individual, group, role, service, or device;"},{"id":"ia-4_obj.d","label":"IA-04d.","text":"system identifiers are managed by preventing reuse of identifiers for {{ insert: param, ia-04_odp.02 }}."}],"methods":[{"method":"examine","label":"IA-04-Examine"},{"method":"interview","label":"IA-04-Interview"},{"method":"test","label":"IA-04-Test"}],"references":[{"title":"FIPS 201-2"},{"title":"SP 800-63-3"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"}],"related_controls":["AC-5","IA-2","IA-3","IA-5","IA-8","IA-9","IA-12","MA-4","PE-2","PE-3","PE-4","PL-4","PM-12","PS-3","PS-4","PS-5","SC-37"],"enhancements":[{"id":"IA-4(1)","oscal_id":"ia-4.1","family":"IA","title":"Prohibit Account Identifiers as Public Identifiers","statement":"Prohibit the use of system account identifiers that are the same as public identifiers for individual accounts.","supplemental_guidance":"Prohibiting account identifiers as public identifiers applies to any publicly disclosed account identifier used for communication such as, electronic mail and instant messaging. Prohibiting the use of systems account identifiers that are the same as some public identifier, such as the individual identifier section of an electronic mail address, makes it more difficult for adversaries to guess user identifiers. Prohibiting account identifiers as public identifiers without the implementation of other supporting controls only complicates guessing of identifiers. Additional protections are required for authenticators and credentials to protect the account.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-04(01)-Examine"},{"method":"interview","label":"IA-04(01)-Interview"},{"method":"test","label":"IA-04(01)-Test"}],"related_controls":["AT-2","PT-7"],"is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(2)","oscal_id":"ia-4.2","family":"IA","title":"Supervisor Authorization","statement":"","is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(3)","oscal_id":"ia-4.3","family":"IA","title":"Multiple Forms of Certification","statement":"","is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(4)","oscal_id":"ia-4.4","family":"IA","title":"Identify User Status","statement":"Manage individual identifiers by uniquely identifying each individual as <characteristics>.","supplemental_guidance":"Characteristics that identify the status of individuals include contractors, foreign nationals, and non-organizational users. Identifying the status of individuals by these characteristics provides additional information about the people with whom organizational personnel are communicating. For example, it might be useful for a government employee to know that one of the individuals on an email message is a contractor.","implementation_level":"organization","parameters":[{"id":"ia-04.04_odp","label":"characteristics"}],"methods":[{"method":"examine","label":"IA-04(04)-Examine"},{"method":"interview","label":"IA-04(04)-Interview"},{"method":"test","label":"IA-04(04)-Test"}],"is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(5)","oscal_id":"ia-4.5","family":"IA","title":"Dynamic Management","statement":"Manage individual identifiers dynamically in accordance with <dynamic identifier policy>.","supplemental_guidance":"In contrast to conventional approaches to identification that presume static accounts for preregistered users, many distributed systems establish identifiers at runtime for entities that were previously unknown. When identifiers are established at runtime for previously unknown entities, organizations can anticipate and provision for the dynamic establishment of identifiers. Pre-established trust relationships and mechanisms with appropriate authorities to validate credentials and related identifiers are essential.","implementation_level":"system","parameters":[{"id":"ia-04.05_odp","label":"dynamic identifier policy"}],"methods":[{"method":"examine","label":"IA-04(05)-Examine"},{"method":"interview","label":"IA-04(05)-Interview"},{"method":"test","label":"IA-04(05)-Test"}],"related_controls":["AC-16"],"is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(6)","oscal_id":"ia-4.6","family":"IA","title":"Cross-organization Management","statement":"Coordinate with the following external organizations for cross-organization management of identifiers: <external organizations>.","supplemental_guidance":"Cross-organization identifier management provides the capability to identify individuals, groups, roles, or devices when conducting cross-organization activities involving the processing, storage, or transmission of information.","implementation_level":"organization","parameters":[{"id":"ia-04.06_odp","label":"external organizations"}],"methods":[{"method":"examine","label":"IA-04(06)-Examine"},{"method":"interview","label":"IA-04(06)-Interview"},{"method":"test","label":"IA-04(06)-Test"}],"related_controls":["AU-16","IA-2","IA-5"],"is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(7)","oscal_id":"ia-4.7","family":"IA","title":"In-person Registration","statement":"","is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(8)","oscal_id":"ia-4.8","family":"IA","title":"Pairwise Pseudonymous Identifiers","statement":"Generate pairwise pseudonymous identifiers.","supplemental_guidance":"A pairwise pseudonymous identifier is an opaque unguessable subscriber identifier generated by an identity provider for use at a specific individual relying party. Generating distinct pairwise pseudonymous identifiers with no identifying information about a subscriber discourages subscriber activity tracking and profiling beyond the operational requirements established by an organization. The pairwise pseudonymous identifiers are unique to each relying party except in situations where relying parties can show a demonstrable relationship justifying an operational need for correlation, or all parties consent to being correlated in such a manner.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-04(08)-Examine"},{"method":"interview","label":"IA-04(08)-Interview"},{"method":"test","label":"IA-04(08)-Test"}],"related_controls":["IA-5"],"is_enhancement":true,"parent_id":"IA-4"},{"id":"IA-4(9)","oscal_id":"ia-4.9","family":"IA","title":"Attribute Maintenance and Protection","statement":"Maintain the attributes for each uniquely identified individual, device, or service in <protected central storage>.","supplemental_guidance":"For each of the entities covered in [IA-2](#ia-2), [IA-3](#ia-3), [IA-8](#ia-8) , and [IA-9](#ia-9) , it is important to maintain the attributes for each authenticated entity on an ongoing basis in a central (protected) store.","implementation_level":"organization","parameters":[{"id":"ia-04.09_odp","label":"protected central storage"}],"methods":[{"method":"examine","label":"IA-04(09)-Examine"},{"method":"interview","label":"IA-04(09)-Interview"},{"method":"test","label":"IA-04(09)-Test"}],"is_enhancement":true,"parent_id":"IA-4"}]},{"id":"IA-5","oscal_id":"ia-5","family":"IA","title":"Authenticator Management","statement":"Manage system authenticators by:\na. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, service, or device receiving the authenticator;\nb. Establishing initial authenticator content for any authenticators issued by the organization;\nc. Ensuring that authenticators have sufficient strength of mechanism for their intended use;\nd. Establishing and implementing administrative procedures for initial authenticator distribution, for lost or compromised or damaged authenticators, and for revoking authenticators;\ne. Changing default authenticators prior to first use;\nf. Changing or refreshing authenticators <time period by authenticator type> or when <events> occur;\ng. Protecting authenticator content from unauthorized disclosure and modification;\nh. Requiring individuals to take, and having devices implement, specific controls to protect authenticators; and\ni. Changing authenticators for group or role accounts when membership to those accounts changes.","supplemental_guidance":"Authenticators include passwords, cryptographic devices, biometrics, certificates, one-time password devices, and ID badges. Device authenticators include certificates and passwords. Initial authenticator content is the actual content of the authenticator (e.g., the initial password). In contrast, the requirements for authenticator content contain specific criteria or characteristics (e.g., minimum password length). Developers may deliver system components with factory default authentication credentials (i.e., passwords) to allow for initial installation and configuration. Default authentication credentials are often well known, easily discoverable, and present a significant risk. The requirement to protect individual authenticators may be implemented via control [PL-4](#pl-4) or [PS-6](#ps-6) for authenticators in the possession of individuals and by controls [AC-3](#ac-3), [AC-6](#ac-6) , and [SC-28](#sc-28) for authenticators stored in organizational systems, including passwords stored in hashed or encrypted formats or files containing encrypted or hashed passwords accessible with administrator privileges.\n\nSystems support authenticator management by organization-defined settings and restrictions for various authenticator characteristics (e.g., minimum password length, validation time window for time synchronous one-time tokens, and number of allowed rejections during the verification stage of biometric authentication). Actions can be taken to safeguard individual authenticators, including maintaining possession of authenticators, not sharing authenticators with others, and immediately reporting lost, stolen, or compromised authenticators. Authenticator management includes issuing and revoking authenticators for temporary access when no longer needed.","implementation_level":"organization","parameters":[{"id":"ia-05_odp.01","label":"time period by authenticator type"},{"id":"ia-05_odp.02","label":"events"}],"objectives":[{"id":"ia-5_obj.a","label":"IA-05a.","text":"system authenticators are managed through the verification of the identity of the individual, group, role, service, or device receiving the authenticator as part of the initial authenticator distribution;"},{"id":"ia-5_obj.b","label":"IA-05b.","text":"system authenticators are managed through the establishment of initial authenticator content for any authenticators issued by the organization;"},{"id":"ia-5_obj.c","label":"IA-05c.","text":"system authenticators are managed to ensure that authenticators have sufficient strength of mechanism for their intended use;"},{"id":"ia-5_obj.d","label":"IA-05d.","text":"system authenticators are managed through the establishment and implementation of administrative procedures for initial authenticator distribution; lost, compromised, or damaged authenticators; and the revocation of authenticators;"},{"id":"ia-5_obj.e","label":"IA-05e.","text":"system authenticators are managed through the change of default authenticators prior to first use;"},{"id":"ia-5_obj.f","label":"IA-05f.","text":"system authenticators are managed through the change or refreshment of authenticators {{ insert: param, ia-05_odp.01 }} or when {{ insert: param, ia-05_odp.02 }} occur;"},{"id":"ia-5_obj.g","label":"IA-05g.","text":"system authenticators are managed through the protection of authenticator content from unauthorized disclosure and modification;"},{"id":"ia-5_obj.h-1","label":"IA-05h.[01]","text":"system authenticators are managed through the requirement for individuals to take specific controls to protect authenticators;"},{"id":"ia-5_obj.h-2","label":"IA-05h.[02]","text":"system authenticators are managed through the requirement for devices to implement specific controls to protect authenticators;"},{"id":"ia-5_obj.i","label":"IA-05i.","text":"system authenticators are managed through the change of authenticators for group or role accounts when membership to those accounts changes."}],"methods":[{"method":"examine","label":"IA-05-Examine"},{"method":"interview","label":"IA-05-Interview"},{"method":"test","label":"IA-05-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 180-4"},{"title":"FIPS 201-2"},{"title":"FIPS 202"},{"title":"SP 800-63-3"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"},{"title":"IR 7539"},{"title":"IR 7817"},{"title":"IR 7849"},{"title":"IR 7870"},{"title":"IR 8040"}],"related_controls":["AC-3","AC-6","CM-6","IA-2","IA-4","IA-7","IA-8","IA-9","MA-4","PE-2","PL-4","SC-12","SC-13"],"enhancements":[{"id":"IA-5(1)","oscal_id":"ia-5.1","family":"IA","title":"Password-based Authentication","statement":"For password-based authentication:\n(a) Maintain a list of commonly-used, expected, or compromised passwords and update the list <frequency> and when organizational passwords are suspected to have been compromised directly or indirectly;\n(b) Verify, when users create or update passwords, that the passwords are not found on the list of commonly-used, expected, or compromised passwords in IA-5(1)(a);\n(c) Transmit passwords only over cryptographically-protected channels;\n(d) Store passwords using an approved salted key derivation function, preferably using a keyed hash;\n(e) Require immediate selection of a new password upon account recovery;\n(f) Allow user selection of long passwords and passphrases, including spaces and all printable characters;\n(g) Employ automated tools to assist the user in selecting strong password authenticators; and\n(h) Enforce the following composition and complexity rules: <composition and complexity rules>.","supplemental_guidance":"Password-based authentication applies to passwords regardless of whether they are used in single-factor or multi-factor authentication. Long passwords or passphrases are preferable over shorter passwords. Enforced composition rules provide marginal security benefits while decreasing usability. However, organizations may choose to establish certain rules for password generation (e.g., minimum character length for long passwords) under certain circumstances and can enforce this requirement in IA-5(1)(h). Account recovery can occur, for example, in situations when a password is forgotten. Cryptographically protected passwords include salted one-way cryptographic hashes of passwords. The list of commonly used, compromised, or expected passwords includes passwords obtained from previous breach corpuses, dictionary words, and repetitive or sequential characters. The list includes context-specific words, such as the name of the service, username, and derivatives thereof.","implementation_level":"organization","parameters":[{"id":"ia-05.01_odp.01","label":"frequency"},{"id":"ia-05.01_odp.02","label":"composition and complexity rules"}],"objectives":[{"id":"ia-5.1_obj.a","label":"IA-05(01)(a)","text":"for password-based authentication, a list of commonly used, expected, or compromised passwords is maintained and updated {{ insert: param, ia-05.01_odp.01 }} and when organizational passwords are suspected to have been compromised directly or indirectly;"},{"id":"ia-5.1_obj.b","label":"IA-05(01)(b)","text":"for password-based authentication when passwords are created or updated by users, the passwords are verified not to be found on the list of commonly used, expected, or compromised passwords in IA-05(01)(a);"},{"id":"ia-5.1_obj.c","label":"IA-05(01)(c)","text":"for password-based authentication, passwords are only transmitted over cryptographically protected channels;"},{"id":"ia-5.1_obj.d","label":"IA-05(01)(d)","text":"for password-based authentication, passwords are stored using an approved salted key derivation function, preferably using a keyed hash;"},{"id":"ia-5.1_obj.e","label":"IA-05(01)(e)","text":"for password-based authentication, immediate selection of a new password is required upon account recovery;"},{"id":"ia-5.1_obj.f","label":"IA-05(01)(f)","text":"for password-based authentication, user selection of long passwords and passphrases is allowed, including spaces and all printable characters;"},{"id":"ia-5.1_obj.g","label":"IA-05(01)(g)","text":"for password-based authentication, automated tools are employed to assist the user in selecting strong password authenticators;"},{"id":"ia-5.1_obj.h","label":"IA-05(01)(h)","text":"for password-based authentication, {{ insert: param, ia-05.01_odp.02 }} are enforced."}],"methods":[{"method":"examine","label":"IA-05(01)-Examine"},{"method":"interview","label":"IA-05(01)-Interview"},{"method":"test","label":"IA-05(01)-Test"}],"related_controls":["IA-6"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(2)","oscal_id":"ia-5.2","family":"IA","title":"Public Key-based Authentication","statement":"(a) For public key-based authentication:\n  For public key-based authentication:\n  (1) Enforce authorized access to the corresponding private key; and\n  (2) Map the authenticated identity to the account of the individual or group; and\n(b) When public key infrastructure (PKI) is used:\n  When public key infrastructure (PKI) is used:\n  (1) Validate certificates by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information; and\n  (2) Implement a local cache of revocation data to support path discovery and validation.","supplemental_guidance":"Public key cryptography is a valid authentication mechanism for individuals, machines, and devices. For PKI solutions, status information for certification paths includes certificate revocation lists or certificate status protocol responses. For PIV cards, certificate validation involves the construction and verification of a certification path to the Common Policy Root trust anchor, which includes certificate policy processing. Implementing a local cache of revocation data to support path discovery and validation also supports system availability in situations where organizations are unable to access revocation information via the network.","implementation_level":"system","objectives":[{"id":"ia-5.2_obj.a.1","label":"IA-05(02)(a)(01)","text":"authorized access to the corresponding private key is enforced for public key-based authentication;"},{"id":"ia-5.2_obj.a.2","label":"IA-05(02)(a)(02)","text":"the authenticated identity is mapped to the account of the individual or group for public key-based authentication;"},{"id":"ia-5.2_obj.b.1","label":"IA-05(02)(b)(01)","text":"when public key infrastructure (PKI) is used, certificates are validated by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information;"},{"id":"ia-5.2_obj.b.2","label":"IA-05(02)(b)(02)","text":"when public key infrastructure (PKI) is used, a local cache of revocation data is implemented to support path discovery and validation."}],"methods":[{"method":"examine","label":"IA-05(02)-Examine"},{"method":"interview","label":"IA-05(02)-Interview"},{"method":"test","label":"IA-05(02)-Test"}],"related_controls":["IA-3","SC-17"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(3)","oscal_id":"ia-5.3","family":"IA","title":"In-person or Trusted External Party Registration","statement":"","is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(4)","oscal_id":"ia-5.4","family":"IA","title":"Automated Support for Password Strength Determination","statement":"","is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(5)","oscal_id":"ia-5.5","family":"IA","title":"Change Authenticators Prior to Delivery","statement":"Require developers and installers of system components to provide unique authenticators or change default authenticators prior to delivery and installation.","supplemental_guidance":"Changing authenticators prior to the delivery and installation of system components extends the requirement for organizations to change default authenticators upon system installation by requiring developers and/or installers to provide unique authenticators or change default authenticators for system components prior to delivery and/or installation. However, it typically does not apply to developers of commercial off-the-shelf information technology products. Requirements for unique authenticators can be included in acquisition documents prepared by organizations when procuring systems or system components.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-05(05)-Examine"},{"method":"interview","label":"IA-05(05)-Interview"},{"method":"test","label":"IA-05(05)-Test"}],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(6)","oscal_id":"ia-5.6","family":"IA","title":"Protection of Authenticators","statement":"Protect authenticators commensurate with the security category of the information to which use of the authenticator permits access.","supplemental_guidance":"For systems that contain multiple security categories of information without reliable physical or logical separation between categories, authenticators used to grant access to the systems are protected commensurate with the highest security category of information on the systems. Security categories of information are determined as part of the security categorization process.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-05(06)-Examine"},{"method":"interview","label":"IA-05(06)-Interview"},{"method":"test","label":"IA-05(06)-Test"}],"related_controls":["RA-2"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(7)","oscal_id":"ia-5.7","family":"IA","title":"No Embedded Unencrypted Static Authenticators","statement":"Ensure that unencrypted static authenticators are not embedded in applications or other forms of static storage.","supplemental_guidance":"In addition to applications, other forms of static storage include access scripts and function keys. Organizations exercise caution when determining whether embedded or stored authenticators are in encrypted or unencrypted form. If authenticators are used in the manner stored, then those representations are considered unencrypted authenticators.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-05(07)-Examine"},{"method":"interview","label":"IA-05(07)-Interview"},{"method":"test","label":"IA-05(07)-Test"}],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(8)","oscal_id":"ia-5.8","family":"IA","title":"Multiple System Accounts","statement":"Implement <security controls> to manage the risk of compromise due to individuals having accounts on multiple systems.","supplemental_guidance":"When individuals have accounts on multiple systems and use the same authenticators such as passwords, there is the risk that a compromise of one account may lead to the compromise of other accounts. Alternative approaches include having different authenticators (passwords) on all systems, employing a single sign-on or federation mechanism, or using some form of one-time passwords on all systems. Organizations can also use rules of behavior (see [PL-4](#pl-4) ) and access agreements (see [PS-6](#ps-6) ) to mitigate the risk of multiple system accounts.","implementation_level":"organization","parameters":[{"id":"ia-05.08_odp","label":"security controls"}],"methods":[{"method":"examine","label":"IA-05(08)-Examine"},{"method":"interview","label":"IA-05(08)-Interview"},{"method":"test","label":"IA-05(08)-Test"}],"related_controls":["PS-6"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(9)","oscal_id":"ia-5.9","family":"IA","title":"Federated Credential Management","statement":"Use the following external organizations to federate credentials: <external organizations>.","supplemental_guidance":"Federation provides organizations with the capability to authenticate individuals and devices when conducting cross-organization activities involving the processing, storage, or transmission of information. Using a specific list of approved external organizations for authentication helps to ensure that those organizations are vetted and trusted.","implementation_level":"organization","parameters":[{"id":"ia-05.09_odp","label":"external organizations"}],"methods":[{"method":"examine","label":"IA-05(09)-Examine"},{"method":"interview","label":"IA-05(09)-Interview"},{"method":"test","label":"IA-05(09)-Test"}],"related_controls":["AU-7","AU-16"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(10)","oscal_id":"ia-5.10","family":"IA","title":"Dynamic Credential Binding","statement":"Bind identities and authenticators dynamically using the following rules: <binding rules>.","supplemental_guidance":"Authentication requires some form of binding between an identity and the authenticator that is used to confirm the identity. In conventional approaches, binding is established by pre-provisioning both the identity and the authenticator to the system. For example, the binding between a username (i.e., identity) and a password (i.e., authenticator) is accomplished by provisioning the identity and authenticator as a pair in the system. New authentication techniques allow the binding between the identity and the authenticator to be implemented external to a system. For example, with smartcard credentials, the identity and authenticator are bound together on the smartcard. Using these credentials, systems can authenticate identities that have not been pre-provisioned, dynamically provisioning the identity after authentication. In these situations, organizations can anticipate the dynamic provisioning of identities. Pre-established trust relationships and mechanisms with appropriate authorities to validate identities and related credentials are essential.","implementation_level":"system","parameters":[{"id":"ia-05.10_odp","label":"binding rules"}],"methods":[{"method":"examine","label":"IA-05(10)-Examine"},{"method":"interview","label":"IA-05(10)-Interview"},{"method":"test","label":"IA-05(10)-Test"}],"related_controls":["AU-16","IA-5"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(11)","oscal_id":"ia-5.11","family":"IA","title":"Hardware Token-based Authentication","statement":"","is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(12)","oscal_id":"ia-5.12","family":"IA","title":"Biometric Authentication Performance","statement":"For biometric-based authentication, employ mechanisms that satisfy the following biometric quality requirements <biometric quality requirements>.","supplemental_guidance":"Unlike password-based authentication, which provides exact matches of user-input passwords to stored passwords, biometric authentication does not provide exact matches. Depending on the type of biometric and the type of collection mechanism, there is likely to be some divergence from the presented biometric and the stored biometric that serves as the basis for comparison. Matching performance is the rate at which a biometric algorithm correctly results in a match for a genuine user and rejects other users. Biometric performance requirements include the match rate, which reflects the accuracy of the biometric matching algorithm used by a system.","implementation_level":"system","parameters":[{"id":"ia-05.12_odp","label":"biometric quality requirements"}],"methods":[{"method":"examine","label":"IA-05(12)-Examine"},{"method":"interview","label":"IA-05(12)-Interview"},{"method":"test","label":"IA-05(12)-Test"}],"related_controls":["AC-7"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(13)","oscal_id":"ia-5.13","family":"IA","title":"Expiration of Cached Authenticators","statement":"Prohibit the use of cached authenticators after <time period>.","supplemental_guidance":"Cached authenticators are used to authenticate to the local machine when the network is not available. If cached authentication information is out of date, the validity of the authentication information may be questionable.","implementation_level":"system","parameters":[{"id":"ia-05.13_odp","label":"time period"}],"methods":[{"method":"examine","label":"IA-05(13)-Examine"},{"method":"interview","label":"IA-05(13)-Interview"},{"method":"test","label":"IA-05(13)-Test"}],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(14)","oscal_id":"ia-5.14","family":"IA","title":"Managing Content of PKI Trust Stores","statement":"For PKI-based authentication, employ an organization-wide methodology for managing the content of PKI trust stores installed across all platforms, including networks, operating systems, browsers, and applications.","supplemental_guidance":"An organization-wide methodology for managing the content of PKI trust stores helps improve the accuracy and currency of PKI-based authentication credentials across the organization.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-05(14)-Examine"},{"method":"interview","label":"IA-05(14)-Interview"},{"method":"test","label":"IA-05(14)-Test"}],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(15)","oscal_id":"ia-5.15","family":"IA","title":"GSA-approved Products and Services","statement":"Use only General Services Administration-approved products and services for identity, credential, and access management.","supplemental_guidance":"General Services Administration (GSA)-approved products and services are products and services that have been approved through the GSA conformance program, where applicable, and posted to the GSA Approved Products List. GSA provides guidance for teams to design and build functional and secure systems that comply with Federal Identity, Credential, and Access Management (FICAM) policies, technologies, and implementation patterns.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-05(15)-Examine"},{"method":"interview","label":"IA-05(15)-Interview"},{"method":"test","label":"IA-05(15)-Test"}],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(16)","oscal_id":"ia-5.16","family":"IA","title":"In-person or Trusted External Party Authenticator Issuance","statement":"Require that the issuance of <types of and/or specific authenticators> be conducted <organization-defined parameter> before <registration authority> with authorization by <personnel or roles>.","supplemental_guidance":"Issuing authenticators in person or by a trusted external party enhances and reinforces the trustworthiness of the identity proofing process.","implementation_level":"organization","parameters":[{"id":"ia-05.16_odp.01","label":"types of and/or specific authenticators"},{"id":"ia-05.16_odp.02","label":"","choices":["in person","by a trusted external party"]},{"id":"ia-05.16_odp.03","label":"registration authority"},{"id":"ia-05.16_odp.04","label":"personnel or roles"}],"methods":[{"method":"examine","label":"IA-05(16)-Examine"},{"method":"interview","label":"IA-05(16)-Interview"},{"method":"test","label":"IA-05(16)-Test"}],"related_controls":["IA-12"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(17)","oscal_id":"ia-5.17","family":"IA","title":"Presentation Attack Detection for Biometric Authenticators","statement":"Employ presentation attack detection mechanisms for biometric-based authentication.","supplemental_guidance":"Biometric characteristics do not constitute secrets. Such characteristics can be obtained by online web accesses, taking a picture of someone with a camera phone to obtain facial images with or without their knowledge, lifting from objects that someone has touched (e.g., a latent fingerprint), or capturing a high-resolution image (e.g., an iris pattern). Presentation attack detection technologies including liveness detection, can mitigate the risk of these types of attacks by making it difficult to produce artifacts intended to defeat the biometric sensor.","implementation_level":"system","methods":[{"method":"examine","label":"IA-05(17)-Examine"},{"method":"interview","label":"IA-05(17)-Interview"},{"method":"test","label":"IA-05(17)-Test"}],"related_controls":["AC-7"],"is_enhancement":true,"parent_id":"IA-5"},{"id":"IA-5(18)","oscal_id":"ia-5.18","family":"IA","title":"Password Managers","statement":"(a) Employ <password managers> to generate and manage passwords; and\n(b) Protect the passwords using <controls>.","supplemental_guidance":"For systems where static passwords are employed, it is often a challenge to ensure that the passwords are suitably complex and that the same passwords are not employed on multiple systems. A password manager is a solution to this problem as it automatically generates and stores strong and different passwords for various accounts. A potential risk of using password managers is that adversaries can target the collection of passwords generated by the password manager. Therefore, the collection of passwords requires protection including encrypting the passwords (see [IA-5(1)(d)](#ia-5.1_smt.d) ) and storing the collection offline in a token.","implementation_level":"system","parameters":[{"id":"ia-05.18_odp.01","label":"password managers"},{"id":"ia-05.18_odp.02","label":"controls"}],"objectives":[{"id":"ia-5.18_obj.a","label":"IA-05(18)(a)","text":"{{ insert: param, ia-05.18_odp.01 }} are employed to generate and manage passwords;"},{"id":"ia-5.18_obj.b","label":"IA-05(18)(b)","text":"the passwords are protected using {{ insert: param, ia-05.18_odp.02 }}."}],"methods":[{"method":"examine","label":"IA-05(18)-Examine"},{"method":"interview","label":"IA-05(18)-Interview"},{"method":"test","label":"IA-05(18)-Test"}],"is_enhancement":true,"parent_id":"IA-5"}]},{"id":"IA-6","oscal_id":"ia-6","family":"IA","title":"Authentication Feedback","statement":"Obscure feedback of authentication information during the authentication process to protect the information from possible exploitation and use by unauthorized individuals.","supplemental_guidance":"Authentication feedback from systems does not provide information that would allow unauthorized individuals to compromise authentication mechanisms. For some types of systems, such as desktops or notebooks with relatively large monitors, the threat (referred to as shoulder surfing) may be significant. For other types of systems, such as mobile devices with small displays, the threat may be less significant and is balanced against the increased likelihood of typographic input errors due to small keyboards. Thus, the means for obscuring authentication feedback is selected accordingly. Obscuring authentication feedback includes displaying asterisks when users type passwords into input devices or displaying feedback for a very limited time before obscuring it.","implementation_level":"system","methods":[{"method":"examine","label":"IA-06-Examine"},{"method":"interview","label":"IA-06-Interview"},{"method":"test","label":"IA-06-Test"}],"related_controls":["AC-3"]},{"id":"IA-7","oscal_id":"ia-7","family":"IA","title":"Cryptographic Module Authentication","statement":"Implement mechanisms for authentication to a cryptographic module that meet the requirements of applicable laws, executive orders, directives, policies, regulations, standards, and guidelines for such authentication.","supplemental_guidance":"Authentication mechanisms may be required within a cryptographic module to authenticate an operator accessing the module and to verify that the operator is authorized to assume the requested role and perform services within that role.","implementation_level":"system","methods":[{"method":"examine","label":"IA-07-Examine"},{"method":"interview","label":"IA-07-Interview"},{"method":"test","label":"IA-07-Test"}],"references":[{"title":"FIPS 140-3"}],"related_controls":["AC-3","IA-5","SA-4","SC-12","SC-13"]},{"id":"IA-8","oscal_id":"ia-8","family":"IA","title":"Identification and Authentication (Non-organizational Users)","statement":"Uniquely identify and authenticate non-organizational users or processes acting on behalf of non-organizational users.","supplemental_guidance":"Non-organizational users include system users other than organizational users explicitly covered by [IA-2](#ia-2) . Non-organizational users are uniquely identified and authenticated for accesses other than those explicitly identified and documented in [AC-14](#ac-14) . Identification and authentication of non-organizational users accessing federal systems may be required to protect federal, proprietary, or privacy-related information (with exceptions noted for national security systems). Organizations consider many factors—including security, privacy, scalability, and practicality—when balancing the need to ensure ease of use for access to federal information and systems with the need to protect and adequately mitigate risk.","implementation_level":"system","methods":[{"method":"examine","label":"IA-08-Examine"},{"method":"interview","label":"IA-08-Interview"},{"method":"test","label":"IA-08-Test"}],"references":[{"title":"OMB A-130"},{"title":"FED PKI"},{"title":"FIPS 201-2"},{"title":"SP 800-63-3"},{"title":"SP 800-79-2"},{"title":"SP 800-116"},{"title":"IR 8062"}],"related_controls":["AC-2","AC-6","AC-14","AC-17","AC-18","AU-6","IA-2","IA-4","IA-5","IA-10","IA-11","IA-13","MA-4","RA-3","SA-4","SC-8"],"enhancements":[{"id":"IA-8(1)","oscal_id":"ia-8.1","family":"IA","title":"Acceptance of PIV Credentials from Other Agencies","statement":"Accept and electronically verify Personal Identity Verification-compliant credentials from other federal agencies.","supplemental_guidance":"Acceptance of Personal Identity Verification (PIV) credentials from other federal agencies applies to both logical and physical access control systems. PIV credentials are those credentials issued by federal agencies that conform to FIPS Publication 201 and supporting guidelines. The adequacy and reliability of PIV card issuers are addressed and authorized using [SP 800-79-2](#10963761-58fc-4b20-b3d6-b44a54daba03).","implementation_level":"system","objectives":[{"id":"ia-8.1_obj-1","label":"IA-08(01)[01]","text":"Personal Identity Verification-compliant credentials from other federal agencies are accepted;"},{"id":"ia-8.1_obj-2","label":"IA-08(01)[02]","text":"Personal Identity Verification-compliant credentials from other federal agencies are electronically verified."}],"methods":[{"method":"examine","label":"IA-08(01)-Examine"},{"method":"interview","label":"IA-08(01)-Interview"},{"method":"test","label":"IA-08(01)-Test"}],"related_controls":["PE-3"],"is_enhancement":true,"parent_id":"IA-8"},{"id":"IA-8(2)","oscal_id":"ia-8.2","family":"IA","title":"Acceptance of External Authenticators","statement":"(a) Accept only external authenticators that are NIST-compliant; and\n(b) Document and maintain a list of accepted external authenticators.","supplemental_guidance":"Acceptance of only NIST-compliant external authenticators applies to organizational systems that are accessible to the public (e.g., public-facing websites). External authenticators are issued by nonfederal government entities and are compliant with [SP 800-63B](#e59c5a7c-8b1f-49ca-8de0-6ee0882180ce) . Approved external authenticators meet or exceed the minimum Federal Government-wide technical, security, privacy, and organizational maturity requirements. Meeting or exceeding Federal requirements allows Federal Government relying parties to trust external authenticators in connection with an authentication transaction at a specified authenticator assurance level.","implementation_level":"system","objectives":[{"id":"ia-8.2_obj.a","label":"IA-08(02)(a)","text":"only external authenticators that are NIST-compliant are accepted;"},{"id":"ia-8.2_obj.b-1","label":"IA-08(02)(b)[01]","text":"a list of accepted external authenticators is documented;"},{"id":"ia-8.2_obj.b-2","label":"IA-08(02)(b)[02]","text":"a list of accepted external authenticators is maintained."}],"methods":[{"method":"examine","label":"IA-08(02)-Examine"},{"method":"interview","label":"IA-08(02)-Interview"},{"method":"test","label":"IA-08(02)-Test"}],"is_enhancement":true,"parent_id":"IA-8"},{"id":"IA-8(3)","oscal_id":"ia-8.3","family":"IA","title":"Use of FICAM-approved Products","statement":"","is_enhancement":true,"parent_id":"IA-8"},{"id":"IA-8(4)","oscal_id":"ia-8.4","family":"IA","title":"Use of Defined Profiles","statement":"Conform to the following profiles for identity management <identity management profiles>.","supplemental_guidance":"Organizations define profiles for identity management based on open identity management standards. To ensure that open identity management standards are viable, robust, reliable, sustainable, and interoperable as documented, the Federal Government assesses and scopes the standards and technology implementations against applicable laws, executive orders, directives, policies, regulations, standards, and guidelines.","implementation_level":"system","parameters":[{"id":"ia-08.04_odp","label":"identity management profiles"}],"methods":[{"method":"examine","label":"IA-08(04)-Examine"},{"method":"interview","label":"IA-08(04)-Interview"},{"method":"test","label":"IA-08(04)-Test"}],"is_enhancement":true,"parent_id":"IA-8"},{"id":"IA-8(5)","oscal_id":"ia-8.5","family":"IA","title":"Acceptance of PIV-I Credentials","statement":"Accept and verify federated or PKI credentials that meet <policy>.","supplemental_guidance":"Acceptance of PIV-I credentials can be implemented by PIV, PIV-I, and other commercial or external identity providers. The acceptance and verification of PIV-I-compliant credentials apply to both logical and physical access control systems. The acceptance and verification of PIV-I credentials address nonfederal issuers of identity cards that desire to interoperate with United States Government PIV systems and that can be trusted by Federal Government-relying parties. The X.509 certificate policy for the Federal Bridge Certification Authority (FBCA) addresses PIV-I requirements. The PIV-I card is commensurate with the PIV credentials as defined in cited references. PIV-I credentials are the credentials issued by a PIV-I provider whose PIV-I certificate policy maps to the Federal Bridge PIV-I Certificate Policy. A PIV-I provider is cross-certified with the FBCA (directly or through another PKI bridge) with policies that have been mapped and approved as meeting the requirements of the PIV-I policies defined in the FBCA certificate policy.","implementation_level":"system","parameters":[{"id":"ia-08.05_odp","label":"policy"}],"objectives":[{"id":"ia-8.5_obj-1","label":"IA-08(05)[01]","text":"federated or PKI credentials that meet {{ insert: param, ia-08.05_odp }} are accepted;"},{"id":"ia-8.5_obj-2","label":"IA-08(05)[02]","text":"federated or PKI credentials that meet {{ insert: param, ia-08.05_odp }} are verified."}],"methods":[{"method":"examine","label":"IA-08(05)-Examine"},{"method":"interview","label":"IA-08(05)-Interview"},{"method":"test","label":"IA-08(05)-Test"}],"is_enhancement":true,"parent_id":"IA-8"},{"id":"IA-8(6)","oscal_id":"ia-8.6","family":"IA","title":"Disassociability","statement":"Implement the following measures to disassociate user attributes or identifier assertion relationships among individuals, credential service providers, and relying parties: <measures>.","supplemental_guidance":"Federated identity solutions can create increased privacy risks due to the tracking and profiling of individuals. Using identifier mapping tables or cryptographic techniques to blind credential service providers and relying parties from each other or to make identity attributes less visible to transmitting parties can reduce these privacy risks.","implementation_level":"organization","parameters":[{"id":"ia-08.06_odp","label":"measures"}],"methods":[{"method":"examine","label":"IA-08(06)-Examine"},{"method":"interview","label":"IA-08(06)-Interview"},{"method":"test","label":"IA-08(06)-Test"}],"is_enhancement":true,"parent_id":"IA-8"}]},{"id":"IA-9","oscal_id":"ia-9","family":"IA","title":"Service Identification and Authentication","statement":"Uniquely identify and authenticate <system services and applications> before establishing communications with devices, users, or other services or applications.","supplemental_guidance":"Services that may require identification and authentication include web applications using digital certificates or services or applications that query a database. Identification and authentication methods for system services and applications include information or code signing, provenance graphs, and electronic signatures that indicate the sources of services. Decisions regarding the validity of identification and authentication claims can be made by services separate from the services acting on those decisions. This can occur in distributed system architectures. In such situations, the identification and authentication decisions (instead of actual identifiers and authentication data) are provided to the services that need to act on those decisions.","implementation_level":"organization","parameters":[{"id":"ia-09_odp","label":"system services and applications"}],"methods":[{"method":"examine","label":"IA-09-Examine"},{"method":"interview","label":"IA-09-Interview"},{"method":"test","label":"IA-09-Test"}],"related_controls":["IA-3","IA-4","IA-5","IA-13","SC-8"],"enhancements":[{"id":"IA-9(1)","oscal_id":"ia-9.1","family":"IA","title":"Information Exchange","statement":"","is_enhancement":true,"parent_id":"IA-9"},{"id":"IA-9(2)","oscal_id":"ia-9.2","family":"IA","title":"Transmission of Decisions","statement":"","is_enhancement":true,"parent_id":"IA-9"}]},{"id":"IA-10","oscal_id":"ia-10","family":"IA","title":"Adaptive Authentication","statement":"Require individuals accessing the system to employ <supplemental authentication techniques or mechanisms> under specific <circumstances or situations>.","supplemental_guidance":"Adversaries may compromise individual authentication mechanisms employed by organizations and subsequently attempt to impersonate legitimate users. To address this threat, organizations may employ specific techniques or mechanisms and establish protocols to assess suspicious behavior. Suspicious behavior may include accessing information that individuals do not typically access as part of their duties, roles, or responsibilities; accessing greater quantities of information than individuals would routinely access; or attempting to access information from suspicious network addresses. When pre-established conditions or triggers occur, organizations can require individuals to provide additional authentication information. Another potential use for adaptive authentication is to increase the strength of mechanism based on the number or types of records being accessed. Adaptive authentication does not replace and is not used to avoid the use of multi-factor authentication mechanisms but can augment implementations of multi-factor authentication.","implementation_level":"organization","parameters":[{"id":"ia-10_odp.01","label":"supplemental authentication techniques or mechanisms"},{"id":"ia-10_odp.02","label":"circumstances or situations"}],"methods":[{"method":"examine","label":"IA-10-Examine"},{"method":"interview","label":"IA-10-Interview"},{"method":"test","label":"IA-10-Test"}],"references":[{"title":"SP 800-63-3"}],"related_controls":["IA-2","IA-8"]},{"id":"IA-11","oscal_id":"ia-11","family":"IA","title":"Re-authentication","statement":"Require users to re-authenticate when <circumstances or situations>.","supplemental_guidance":"In addition to the re-authentication requirements associated with device locks, organizations may require re-authentication of individuals in certain situations, including when roles, authenticators or credentials change, when security categories of systems change, when the execution of privileged functions occurs, after a fixed time period, or periodically.","implementation_level":"organization","parameters":[{"id":"ia-11_odp","label":"circumstances or situations"}],"methods":[{"method":"examine","label":"IA-11-Examine"},{"method":"interview","label":"IA-11-Interview"},{"method":"test","label":"IA-11-Test"}],"related_controls":["AC-3","AC-11","IA-2","IA-3","IA-4","IA-8"]},{"id":"IA-12","oscal_id":"ia-12","family":"IA","title":"Identity Proofing","statement":"a. Identity proof users that require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines;\nb. Resolve user identities to a unique individual; and\nc. Collect, validate, and verify identity evidence.","supplemental_guidance":"Identity proofing is the process of collecting, validating, and verifying a user’s identity information for the purposes of establishing credentials for accessing a system. Identity proofing is intended to mitigate threats to the registration of users and the establishment of their accounts. Standards and guidelines specifying identity assurance levels for identity proofing include [SP 800-63-3](#737513fa-6758-403f-831d-5ddab5e23cb3) and [SP 800-63A](#9099ed2c-922a-493d-bcb4-d896192243ff) . Organizations may be subject to laws, executive orders, directives, regulations, or policies that address the collection of identity evidence. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements.","implementation_level":"organization","objectives":[{"id":"ia-12_obj.a","label":"IA-12a.","text":"users who require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines are identity proofed;"},{"id":"ia-12_obj.b","label":"IA-12b.","text":"user identities are resolved to a unique individual;"},{"id":"ia-12_obj.c-1","label":"IA-12c.[01]","text":"identity evidence is collected;"},{"id":"ia-12_obj.c-2","label":"IA-12c.[02]","text":"identity evidence is validated;"},{"id":"ia-12_obj.c-3","label":"IA-12c.[03]","text":"identity evidence is verified."}],"methods":[{"method":"examine","label":"IA-12-Examine"},{"method":"interview","label":"IA-12-Interview"},{"method":"test","label":"IA-12-Test"}],"references":[{"title":"FIPS 201-2"},{"title":"SP 800-63-3"},{"title":"SP 800-63A"},{"title":"SP 800-79-2"}],"related_controls":["AC-5","IA-1","IA-2","IA-3","IA-4","IA-5","IA-6","IA-8","IA-13"],"enhancements":[{"id":"IA-12(1)","oscal_id":"ia-12.1","family":"IA","title":"Supervisor Authorization","statement":"Require that the registration process to receive an account for logical access includes supervisor or sponsor authorization.","supplemental_guidance":"Including supervisor or sponsor authorization as part of the registration process provides an additional level of scrutiny to ensure that the user’s management chain is aware of the account, the account is essential to carry out organizational missions and functions, and the user’s privileges are appropriate for the anticipated responsibilities and authorities within the organization.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-12(01)-Examine"},{"method":"interview","label":"IA-12(01)-Interview"},{"method":"test","label":"IA-12(01)-Test"}],"is_enhancement":true,"parent_id":"IA-12"},{"id":"IA-12(2)","oscal_id":"ia-12.2","family":"IA","title":"Identity Evidence","statement":"Require evidence of individual identification be presented to the registration authority.","supplemental_guidance":"Identity evidence, such as documentary evidence or a combination of documents and biometrics, reduces the likelihood of individuals using fraudulent identification to establish an identity or at least increases the work factor of potential adversaries. The forms of acceptable evidence are consistent with the risks to the systems, roles, and privileges associated with the user’s account.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-12(02)-Examine"},{"method":"interview","label":"IA-12(02)-Interview"},{"method":"test","label":"IA-12(02)-Test"}],"is_enhancement":true,"parent_id":"IA-12"},{"id":"IA-12(3)","oscal_id":"ia-12.3","family":"IA","title":"Identity Evidence Validation and Verification","statement":"Require that the presented identity evidence be validated and verified through <methods of validation and verification>.","supplemental_guidance":"Validation and verification of identity evidence increases the assurance that accounts and identifiers are being established for the correct user and authenticators are being bound to that user. Validation refers to the process of confirming that the evidence is genuine and authentic, and the data contained in the evidence is correct, current, and related to an individual. Verification confirms and establishes a linkage between the claimed identity and the actual existence of the user presenting the evidence. Acceptable methods for validating and verifying identity evidence are consistent with the risks to the systems, roles, and privileges associated with the users account.","implementation_level":"organization","parameters":[{"id":"ia-12.03_odp","label":"methods of validation and verification"}],"methods":[{"method":"examine","label":"IA-12(03)-Examine"},{"method":"interview","label":"IA-12(03)-Interview"},{"method":"test","label":"IA-12(03)-Test"}],"is_enhancement":true,"parent_id":"IA-12"},{"id":"IA-12(4)","oscal_id":"ia-12.4","family":"IA","title":"In-person Validation and Verification","statement":"Require that the validation and verification of identity evidence be conducted in person before a designated registration authority.","supplemental_guidance":"In-person proofing reduces the likelihood of fraudulent credentials being issued because it requires the physical presence of individuals, the presentation of physical identity documents, and actual face-to-face interactions with designated registration authorities.","implementation_level":"organization","methods":[{"method":"examine","label":"IA-12(04)-Examine"},{"method":"interview","label":"IA-12(04)-Interview"},{"method":"test","label":"IA-12(04)-Test"}],"is_enhancement":true,"parent_id":"IA-12"},{"id":"IA-12(5)","oscal_id":"ia-12.5","family":"IA","title":"Address Confirmation","statement":"Require that a <organization-defined parameter> be delivered through an out-of-band channel to verify the users address (physical or digital) of record.","supplemental_guidance":"To make it more difficult for adversaries to pose as legitimate users during the identity proofing process, organizations can use out-of-band methods to ensure that the individual associated with an address of record is the same individual that participated in the registration. Confirmation can take the form of a temporary enrollment code or a notice of proofing. The delivery address for these artifacts is obtained from records and not self-asserted by the user. The address can include a physical or digital address. A home address is an example of a physical address. Email addresses and telephone numbers are examples of digital addresses.","implementation_level":"organization","parameters":[{"id":"ia-12.05_odp","label":"","choices":["registration code","notice of proofing"]}],"methods":[{"method":"examine","label":"IA-12(05)-Examine"},{"method":"interview","label":"IA-12(05)-Interview"},{"method":"test","label":"IA-12(05)-Test"}],"related_controls":["IA-12"],"is_enhancement":true,"parent_id":"IA-12"},{"id":"IA-12(6)","oscal_id":"ia-12.6","family":"IA","title":"Accept Externally-proofed Identities","statement":"Accept externally-proofed identities at <identity assurance level>.","supplemental_guidance":"To limit unnecessary re-proofing of identities, particularly of non-PIV users, organizations accept proofing conducted at a commensurate level of assurance by other agencies or organizations. Proofing is consistent with organizational security policy and the identity assurance level appropriate for the system, application, or information accessed. Accepting externally-proofed identities is a fundamental component of managing federated identities across agencies and organizations.","implementation_level":"organization","parameters":[{"id":"ia-12.06_odp","label":"identity assurance level"}],"methods":[{"method":"examine","label":"IA-12(06)-Examine"},{"method":"interview","label":"IA-12(06)-Interview"},{"method":"test","label":"IA-12(06)-Test"}],"related_controls":["IA-3","IA-4","IA-5","IA-8"],"is_enhancement":true,"parent_id":"IA-12"}]},{"id":"IA-13","oscal_id":"ia-13","family":"IA","title":"Identity Providers and Authorization Servers","statement":"Employ identity providers and authorization servers to manage user, device, and non-person entity (NPE) identities, attributes, and access rights supporting authentication and authorization decisions in accordance with <policy> using <mechanisms>.","supplemental_guidance":"Identity providers, both internal and external to the organization, manage the user, device, and NPE authenticators and issue statements, often called identity assertions, attesting to identities of other systems or systems components. Authorization servers create and issue access tokens to identified and authenticated users and devices that can be used to gain access to system or information resources. For example, single sign-on (SSO) provides identity provider and authorization server functions. Authenticator management (to include credential management) is covered by IA-05.","implementation_level":"organization","parameters":[{"id":"ia-13_odp.01","label":"policy"},{"id":"ia-13_odp.02","label":"mechanisms"}],"objectives":[{"id":"ia-13_obj-1","label":"IA-13[01]","text":"identity providers are employed to manage user, device, and non-person entity (NPE) identities, attributes and access rights supporting authentication decisions in accordance with {{ insert: param, ia-13_odp.02 }} using {{ insert: param, ia-13_odp.02 }};"},{"id":"ia-13_obj-2","label":"IA-13[02]","text":"identity providers are employed to manage user, device, and non-person entity (NPE) identities, attributes and access rights supporting authorization decisions in accordance with {{ insert: param, ia-13_odp.02 }} using {{ insert: param, ia-13_odp.02 }};"},{"id":"ia-13_obj-3","label":"IA-13[03]","text":"authorization servers are employed to manage user, device, and non-person entity (NPE) identities, attributes and access rights supporting authentication decisions in accordance with {{ insert: param, ia-13_odp.02 }} using {{ insert: param, ia-13_odp.02 }};"},{"id":"ia-13_obj-4","label":"IA-13[04]","text":"authorization servers are employed to manage user, device, and non-person entity (NPE) identities, attributes and access rights supporting authorization decisions in accordance with {{ insert: param, ia-13_odp.02 }} using {{ insert: param, ia-13_odp.02 }};"}],"methods":[{"method":"examine","label":"IA-13-Examine"},{"method":"interview","label":"IA-13-Interview"},{"method":"test","label":"IA-13-Test"}],"related_controls":["AC-3","IA-2","IA-3","IA-8","IA-9","IA-12"],"enhancements":[{"id":"IA-13(1)","oscal_id":"ia-13.1","family":"IA","title":"Protection of Cryptographic Keys","statement":"Cryptographic keys that protect access tokens are generated, managed, and protected from disclosure and misuse.","supplemental_guidance":"Identity assertions and access tokens are typically digitally signed. The private keys used to sign these assertions and tokens are protected commensurate with the impact of the system and information resources that can be accessed.","implementation_level":"organization","objectives":[{"id":"ia-13.1_obj-1","label":"IA-13(01)[01]","text":"cryptographic keys that protect access tokens are generated;"},{"id":"ia-13.1_obj-2","label":"IA-13(01)[02]","text":"cryptographic keys that protect access tokens are managed;"},{"id":"ia-13.1_obj-3","label":"IA-13(01)[03]","text":"cryptographic keys that protect access tokens are protected from disclosure; and"},{"id":"ia-13.1_obj-4","label":"IA-13(01)[04]","text":"cryptographic keys that protect access tokens are protected from disclosure and misuse"}],"methods":[{"method":"examine","label":"IA-13(01)-Examine"},{"method":"interview","label":"IA-13(01)-Interview"},{"method":"test","label":"IA-13(01)-Test"}],"related_controls":["SC-12","SC-13"],"is_enhancement":true,"parent_id":"IA-13"},{"id":"IA-13(2)","oscal_id":"ia-13.2","family":"IA","title":"Verification of Identity Assertions and Access Tokens","statement":"The source and integrity of identity assertions and access tokens are verified before granting access to system and information resources.","supplemental_guidance":"This includes verification of digital signatures protecting identity assertions and access tokens, as well as included metadata. Metadata includes information about the access request such as information unique to user, system or information resource being accessed, or the transaction itself such as time. Protected system and information resources could include connected networks, applications, and APIs.","implementation_level":"organization","objectives":[{"id":"ia-13.2_obj-1","label":"IA-13(02)[01]","text":"the source of identity assertions is verified before granting access to system and information resources;"},{"id":"ia-13.2_obj-2","label":"IA-13(02)[02]","text":"the source of access tokens is verified before granting access to system and information resources;"},{"id":"ia-13.2_obj-3","label":"IA-13(02)[03]","text":"the integrity of identity assertions is verified before granting access to system and information resources;"},{"id":"ia-13.2_obj-4","label":"IA-13(02)[04]","text":"the integrity of access tokens is verified before granting access to system and information resources"}],"methods":[{"method":"examine","label":"IA-13(02)-Examine"},{"method":"interview","label":"IA-13(02)-Interview"},{"method":"test","label":"IA-13(02)-Test"}],"is_enhancement":true,"parent_id":"IA-13"},{"id":"IA-13(3)","oscal_id":"ia-13.3","family":"IA","title":"Token Management","statement":"In accordance with <organization-defined parameter>, assertions and access tokens are:\n(a) generated;\n(b) issued;\n(c) refreshed;\n(d) revoked;\n(e) time-restricted; and\n(f) audience-restricted.","supplemental_guidance":"An access token is a piece of data that represents the authorization granted to a user or NPE to access specific systems or information resources. Access tokens enable controlled access to services and resources. Properly managing the lifecycle of access tokens, including their issuance, validation, and revocation, is crucial to maintaining confidentiality of data and systems. Restricting token validity to a specific audience, e.g., an application or security domain, and restricting token validity lifetimes are important practices. Access tokens are revoked or invalidated if they are compromised, lost, or are no longer needed to mitigate the risks associated with stolen or misused tokens.","implementation_level":"organization","objectives":[{"id":"ia-13.3_obj.a-1","label":"IA-13(03)(a)[01]","text":"assertions are generated in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.a-2","label":"IA-13(03)(a)[02]","text":"access tokens are generated in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.b-1","label":"IA-13(03)(b)[01]","text":"assertions are issued in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.b-2","label":"IA-13(03)(b)[02]","text":"access tokens are issued in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.c-1","label":"IA-13(03)(c)[01]","text":"assertions are refreshed in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.c-2","label":"IA-13(03)(c)[02]","text":"access tokens are refreshed in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.d-1","label":"IA-13(03)(d)[01]","text":"assertions are revoked in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.d-2","label":"IA-13(03)(d)[02]","text":"access tokens are revoked in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.e-1","label":"IA-13(03)(e)[01]","text":"assertions are time-restricted in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.e-2","label":"IA-13(03)(e)[02]","text":"access tokens are time-restricted in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.f-1","label":"IA-13(03)(f)[01]","text":"assertions are audience-restricted in accordance with {{ insert: param, ia-13_odp.01 }};"},{"id":"ia-13.3_obj.f-2","label":"IA-13(03)(f)[02]","text":"access tokens are audience-restricted in accordance with {{ insert: param, ia-13_odp.01 }};"}],"methods":[{"method":"examine","label":"IA-13(03)-Examine"},{"method":"interview","label":"IA-13(03)-Interview"},{"method":"test","label":"IA-13(03)-Test"}],"references":[{"title":"SP 800-63-3"},{"title":"FIPS 196"},{"title":"FIPS 198-1"}],"is_enhancement":true,"parent_id":"IA-13"}]}]};
